-- 1. 21 missions (catalog 80 to 100), every one a draft
insert into public.action_missions
  (id, campaign_id, title, description, domain, difficulty, base_points, proof_required, verification_mode,
   skills, capacity, status, starts_at, ends_at, kind, discovery_category)
select v.id, null, v.title, v.description, v.domain, v.difficulty, v.base_points, true, v.verification_mode,
       v.skills, null, 'draft', null, null, 'civic', v.discovery_category
  from (values
    ('1a9c8fcb-2a76-56de-b019-9c1f23a19800'::uuid, -- drawdown-deploy-enhanced-rock-weathering
     'Explain how crushed rock can absorb carbon',
     'Some rocks slowly react with carbon dioxide as they break down, and spreading crushed rock on fields could speed this up. Read reliable sources, then make a short explainer, comic or video in plain words, including what is still being tested. Post it with sources.',
     'education', 'create', 2, 100, 'review', array['research','teaching']::text[]),
    ('2bab59bf-f317-5962-bdaa-2ee1ebbb664a'::uuid, -- drawdown-reduce-grazing-intensity
     'Explain why grazed land needs time to rest',
     'Read reliable sources about what happens to grassland when too many animals graze it for too long, and how fewer animals or longer rest periods let plants and soil recover. Make a short explainer, comic or poster in plain words. Post it with your sources.',
     'education', 'create', 1, 100, 'review', array['research','teaching']::text[]),
    ('3f646f9c-5619-54ed-b38a-3977d359c61c'::uuid, -- drawdown-restore-large-herbivores
     'Find out which big grazers once roamed your region',
     'Research which large plant-eating animals, such as bison, elk or others, once lived in your region and whether any are being brought back. Make a poster or post with what you found, including what scientists are still unsure about. Post it with your sources.',
     'research', 'create', 2, 100, 'review', array['research','design']::text[]),
    ('3933adb5-41e2-57fc-9f40-a2cf8f7ab0f4'::uuid, -- drawdown-deploy-ocean-alkalinity-enhancement
     'Write a fair explainer on changing seawater chemistry',
     'Read reliable sources about ocean alkalinity enhancement, which means adding certain minerals to seawater so it can take up more carbon dioxide. Write a short, balanced explainer that covers how it works, what field studies are testing and what concerns people have raised. Post it with sources.',
     'research', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('9f0aea98-532e-5160-8e48-eb1f76dcea68'::uuid, -- drawdown-deploy-ocean-electrochemistry
     'Gather your questions about ocean carbon removal',
     'Read an introduction to ocean electrochemistry, which uses electricity to change seawater so it can help remove carbon dioxide, from a university or agency source. Write down your own questions about it, then look for answers in reliable sources and note which ones are still open. Post your questions and answers with sources.',
     'research', 'explore', 2, 100, 'review', array['research','writing']::text[]),
    ('747455c5-6ce7-5aa0-9363-e3dd41f8e954'::uuid, -- drawdown-restore-whale-populations
     'Write a short kids'' story about whales',
     'Read about whales from reliable sources, such as an aquarium, museum or marine agency, including how whaling once cut their numbers and how some populations are recovering. Write a short story or picture-book page for kids that shares one true fact. Post your story with your sources.',
     'creative', 'create', 1, 100, 'review', array['writing','research']::text[]),
    ('91846487-707c-509d-b421-488fcd896853'::uuid, -- drawdown-bury-biomass
     'Find out what happens to your town''s yard waste',
     'Check your local waste agency''s website to learn where leaves, branches and other yard waste go after collection, such as composting, mulching, burning or landfill. Write a short summary, and add a note with a source on the idea of storing carbon by burying wood so it can''t rot. Post it with links.',
     'research', 'explore', 1, 100, 'review', array['research','writing']::text[]),
    ('7f666cb5-019d-5542-9809-9f8e606e13ab'::uuid, -- drawdown-use-methane-oxidizing-coatings
     'Explain methane in plain words',
     'Make a short explainer, poster or video about methane: where it comes from, why it matters for the climate, and new ideas researchers are testing to break it down, such as special coatings on roofs. Use reliable sources and list them. Post it.',
     'education', 'create', 1, 100, 'review', array['research','teaching']::text[]),
    ('4038956a-ca7c-562f-91bd-3503247de3cf'::uuid, -- drawdown-manage-coal-mine-methane
     'Map coal mines in your region using public data',
     'Use public data, such as your government''s mining records or a reputable open database of coal mines, to find coal mines in your region or country, including closed ones. Note whether any public rules or reports mention capturing the methane gas that escapes from mines, and make a short map or table with sources. Post it.',
     'research', 'explore', 3, 150, 'review', array['research','data-analysis','mapping']::text[]),
    ('a14f8bcc-20bc-5624-b7af-1105cfcea5e5'::uuid, -- drawdown-manage-oil-gas-methane
     'Write a public comment on oil and gas methane',
     'Look through official sources, such as your environmental agency''s rulemaking page or the government''s public comment portal, for an open proposal about methane leaks from oil and gas operations. Read the plain-language summary and write a short, respectful comment in your own words, then submit it, or save it as a draft if nothing is open right now. Post a link or screenshot with personal details hidden.',
     'advocacy', 'create', 3, 150, 'review', array['policy-analysis','writing']::text[]),
    ('472f9ccf-b9cd-5567-84e0-fb00b634e3ec'::uuid, -- drawdown-use-nitrous-oxide-removal
     'Explain nitrous oxide''s role in climate change',
     'Nitrous oxide is a powerful greenhouse gas, and most of the nitrous oxide that people add to the air comes from farming, especially fertilizer use, with smaller shares from industry and other sources. Read reliable sources and make a short explainer, poster or video about where it comes from and the early research into removing it from the air. Post it with sources.',
     'education', 'create', 2, 100, 'review', array['research','teaching']::text[]),
    ('f28ecf0f-2992-5816-96aa-51e8c71aad36'::uuid, -- drawdown-deploy-concentrated-solar
     'Explain the two main kinds of solar power',
     'Learn the difference between solar panels, which turn sunlight straight into electricity, and concentrated solar plants, which use mirrors to focus sunlight into heat that drives a generator. Make a simple poster, comic or post that shows both side by side, with sources. Post a photo or link.',
     'education', 'create', 1, 100, 'review', array['design','teaching']::text[]),
    ('ce76cfb0-b91f-54cf-bf86-12f19f3721e8'::uuid, -- drawdown-deploy-geothermal-power
     'Map geothermal energy sites in your region',
     'Use public maps from a geological survey or energy agency to find geothermal power plants, hot springs or underground heat resources in your region, or the nearest ones if there are none close by. Mark them on a simple map and add a sentence on how geothermal power uses heat from underground. Post your map with sources.',
     'research', 'explore', 2, 100, 'review', array['research','mapping']::text[]),
    ('cc530601-de9e-5e1a-a527-6c0c3b406ed8'::uuid, -- drawdown-improve-grid-efficiency
     'Ask your utility a public question about the grid',
     'Find your electric utility''s most recent public plan for its grid, often called a long-term resource plan or grid upgrade plan, on its website or your energy regulator''s website. Write one clear question about how it plans to cut the power lost along its wires, and send it through the official comment or contact channel. Post your question and any reply.',
     'advocacy', 'create', 2, 100, 'review', array['policy-analysis','writing']::text[]),
    ('7d91c8c4-dfde-5a47-a4eb-8a9cc2b5f164'::uuid, -- drawdown-deploy-nuclear-power
     'Chart where your home''s electricity comes from',
     'Find your electricity supplier''s fuel mix, which is often published in a yearly disclosure, printed on bills or shown on a government energy website, and see how much comes from nuclear, gas, coal, wind, solar and other sources. Turn it into a simple pie chart or drawing and share it with your household or neighbors. Post a photo of your chart and the source.',
     'research', 'explore', 1, 100, 'review', array['research','data-analysis']::text[]),
    ('57d485fb-678b-59df-ac98-1bf8e967151d'::uuid, -- drawdown-boost-industrial-efficiency
     'Profile a local business that cuts its energy use',
     'Ask a small local business, such as a bakery, print shop or workshop, whether they have done anything to use less energy, like changing equipment schedules or fixing leaks. With the owner''s permission, write a short profile of what they did and why. Post the profile with any photos they agreed to.',
     'business', 'explore', 2, 100, 'review', array['interviewing','writing']::text[]),
    ('84e494bd-6005-53d1-bd0e-118464f74006'::uuid, -- drawdown-increase-industrial-electrification
     'List the large industrial sites near you',
     'Use a public pollution or emissions database from your national environmental agency to list the large industrial facilities in your area, what they make and, where the database says, which fuels they burn for heat. Turn it into a simple map or table so neighbors know what is nearby. Post it with links to the source.',
     'research', 'explore', 2, 100, 'review', array['research','data-analysis','mapping']::text[]),
    ('fbc5cefc-3a2a-5248-b1ea-4ce33c7f68de'::uuid, -- drawdown-deploy-low-emission-industrial-feedstocks
     'Trace the raw materials of an everyday product',
     'Pick an everyday item, such as a plastic bottle, a bag of fertilizer or a cleaning product, and use reliable sources to find out what raw materials it starts from and how they are processed. Draw a simple flow chart from raw material to the item in your hands. Post a photo of your chart with sources.',
     'research', 'create', 2, 100, 'review', array['research','design']::text[]),
    ('b873229b-271c-5d8f-8aae-a8ca6f48adb9'::uuid, -- drawdown-improve-other-building-materials
     'Photograph the building materials on a local street',
     'Walk along a public street you like, such as a main street or a road by a park; it doesn''t have to be your own. Take close-up photos of the materials you can see in buildings and walls, such as brick, wood, concrete, stone, steel and glass. Make a labeled collage, and add a note with a source on one material that builders are trying to make with less pollution. Post the collage.',
     'creative', 'explore', 1, 100, 'review', array['photography','research']::text[]),
    ('b6b35fdf-9966-5375-81a8-06dfb8210d90'::uuid, -- drawdown-improve-aviation-efficiency
     'Read your nearest airport''s climate plan',
     'Find your nearest airport''s sustainability or climate plan on its official website. Write a short, plain-language summary of what it says about saving fuel and cutting emissions on the ground and in the air, and list one question you still have. Post your summary with a link.',
     'research', 'explore', 2, 100, 'review', array['research','writing']::text[]),
    ('746f7501-6f2e-53ac-9b95-695dfa524285'::uuid, -- drawdown-mobilize-electric-buses
     'Ask your transit agency about its bus fleet plans',
     'Find your transit agency''s public plans for its buses, such as a fleet plan or board meeting materials, and check whether electric buses are part of them. Send a short public question or comment through the official channel or at a public meeting, mentioning the routes that matter to your neighbors. Post your question and any reply.',
     'advocacy', 'create', 2, 100, 'review', array['policy-analysis','writing']::text[])
  ) as v(id, title, description, domain, discovery_category, difficulty, base_points, verification_mode, skills)
on conflict (id) do nothing;

