     null,
     null,
     'https://drawdown.org/explorer/manage-coal-mine-methane', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.24020621'),
    ('a14f8bcc-20bc-5624-b7af-1105cfcea5e5'::uuid, 'drawdown-manage-oil-gas-methane',
